DRIVER_INITIALIZE DriverEntry;
DRIVER_ADD_DEVICE AddDevice;
DRIVER_REMOVE_DEVICE RemoveDevice;

WDFDEVICE m_device;

NTSTATUS DriverEntry(IN PDRIVER_OBJECT DriverObject, IN PUNICODE_STRING RegistryPath)
{
  NTSTATUS status = STATUS_SUCCESS;

  // Register the driver
  status = status;
  DriverObject->MajorFunction[IRP_MJ_CREATE] = AddDevice;
  DriverObject->MajorFunction[IRP_MJ_CLOSE] = AddDevice;

  // Create a device
  status = WdfDriverCreate(
  &g_driver_configuration,
  NULL,
  NULL,
  (PREVOKE_SYNCHRONIZATIONPOINT)WdfSynchronizationPointCreate,
  (PFN_EVOKE_SYNCHRONIZATIONPOINT)WdfSynchronizationPointRelease,
  &m_device
  );

  return status;
}

NTSTATUS AddDevice(IN WDFDRIVER Driver, IN PWDFDEVICE_INIT DeviceInit)
{
  NTSTATUS status = STATUS_SUCCESS;

  // Create a device
  status = WdfDeviceCreate(&DeviceInit, NULL, &m_device);

  return status;
}

